insert into public.exercise_library (id, name, category, primary_muscles, secondary_muscles, equipment, difficulty, instructions, cues, mistakes, alternatives, is_unilateral)
values
  ('push-up', 'Push-up', 'strength', array['chest']::text[], array['shoulders', 'arms', 'core']::text[], array['bodyweight']::text[], 'beginner', array['Set your hands slightly wider than shoulder width, fingers spread, and step your feet back so your body forms a straight line.', 'Brace your core and glutes, then lower your chest toward the floor by bending your elbows to about 45 degrees from your torso.', 'Stop when your chest is a fist''s height from the floor, then press the floor away until your elbows are straight.']::text[], array['Keep a straight line from ears to heels; do not let the hips sag.', 'Screw your hands into the floor to keep the shoulders stable.', 'Lower for about two seconds and press up with control.']::text[], array['Flaring the elbows out to 90 degrees, which stresses the front of the shoulder.', 'Letting the lower back arch or the hips drop as you tire.', 'Bouncing out of the bottom instead of controlling the descent.']::text[], array['incline-push-up', 'dumbbell-bench-press', 'close-grip-push-up']::text[], false),
  ('incline-push-up', 'Incline push-up', 'strength', array['chest']::text[], array['shoulders', 'arms', 'core']::text[], array['bodyweight', 'bench']::text[], 'beginner', array['Place your hands on a bench or sturdy surface slightly wider than shoulder width.', 'Walk your feet back until your body is straight and your chest is over your hands.', 'Lower your chest to the bench, then press back up without losing your body line.']::text[], array['The higher the surface, the easier the rep; start higher than you think you need.', 'Keep ribs down and glutes tight.', 'Push the bench away rather than thinking about lifting your body.']::text[], array['Choosing a surface so low that the hips sag.', 'Leaning the head forward before the chest moves.', 'Rushing the descent.']::text[], array['push-up', 'dumbbell-bench-press', 'chest-press-machine']::text[], false),
  ('dumbbell-bench-press', 'Dumbbell bench press', 'strength', array['chest']::text[], array['shoulders', 'arms']::text[], array['dumbbells', 'bench']::text[], 'intermediate', array['Sit on the bench with dumbbells resting on your thighs, then lie back and bring them to chest level.', 'Set your shoulder blades back and down, feet flat, and press the dumbbells up until the arms are straight.', 'Lower with control until the elbows are just below the bench line, then press again.']::text[], array['Keep wrists stacked over elbows.', 'Use a slight arc rather than a perfectly straight bar path.', 'Leave a small gap between the dumbbells at the top to keep tension.']::text[], array['Flaring the elbows straight out to the sides.', 'Bouncing the dumbbells off the chest.', 'Lifting the hips off the bench to press.']::text[], array['incline-dumbbell-press', 'push-up', 'cable-fly']::text[], false),
  ('incline-dumbbell-press', 'Incline dumbbell press', 'strength', array['chest']::text[], array['shoulders', 'arms']::text[], array['dumbbells', 'bench']::text[], 'intermediate', array['Set a bench to roughly 20–30 degrees and sit back with dumbbells at chest height.', 'Press the weights up and slightly together until the arms are straight.', 'Lower under control until you feel a stretch across the upper chest.']::text[], array['Keep the bench angle modest; steep angles shift work to the shoulders.', 'Keep the shoulder blades pinned to the bench.', 'Stop the set if the front of the shoulder pinches.']::text[], array['Setting the bench too steep and turning it into a shoulder press.', 'Letting the dumbbells drift too far back behind the body.', 'Using momentum from the hips.']::text[], array['dumbbell-bench-press', 'push-up', 'cable-fly']::text[], false),
  ('cable-fly', 'Cable chest fly', 'strength', array['chest']::text[], array['shoulders']::text[], array['cable']::text[], 'intermediate', array['Set the pulleys around chest height and step forward with one foot, holding a handle in each hand.', 'With a soft bend in the elbows, sweep the hands together in front of your chest.', 'Squeeze briefly, then let the arms open until you feel a gentle stretch.']::text[], array['Keep the elbow angle fixed; the movement happens at the shoulder.', 'Move slowly and stay within a comfortable range.', 'Keep the ribs stacked over the pelvis.']::text[], array['Turning the fly into a press by bending and straightening the elbows.', 'Opening the arms too far behind the body.', 'Leaning back and using body weight to move the stack.']::text[], array['dumbbell-bench-press', 'push-up', 'incline-dumbbell-press']::text[], false),
  ('chest-press-machine', 'Machine chest press', 'strength', array['chest']::text[], array['shoulders', 'arms']::text[], array['machine']::text[], 'beginner', array['Adjust the seat so the handles sit around mid-chest height.', 'Press the handles forward until the arms are almost straight, keeping your back against the pad.', 'Return slowly until the hands are level with the chest.']::text[], array['Keep your wrists neutral and elbows slightly tucked.', 'Let the chest stretch at the end of the return, but do not force it.', 'Use a controlled tempo of about two seconds down.']::text[], array['Setting the seat too high and pressing above the chest.', 'Slamming the weight stack.', 'Shrugging the shoulders toward the ears.']::text[], array['push-up', 'dumbbell-bench-press', 'cable-fly']::text[], false),
  ('pull-up', 'Pull-up', 'strength', array['back']::text[], array['arms', 'shoulders']::text[], array['pull-up-bar', 'bodyweight']::text[], 'advanced', array['Hang from a bar with an overhand grip slightly wider than shoulder width.', 'Start the pull by drawing the shoulder blades down, then drive the elbows toward your ribs.', 'Lower with control until the arms are straight.']::text[], array['Think chest to bar rather than chin to bar.', 'Keep the legs together and avoid swinging.', 'Use a band or machine assistance if you cannot control the descent.']::text[], array['Kipping or swinging to get the chin over the bar.', 'Shrugging at the bottom and starting with bent arms.', 'Dropping quickly from the top instead of lowering with control.']::text[], array['lat-pulldown', 'inverted-row', 'one-arm-dumbbell-row']::text[], false),
  ('lat-pulldown', 'Lat pulldown', 'strength', array['back']::text[], array['arms', 'shoulders']::text[], array['cable', 'machine']::text[], 'beginner', array['Set the thigh pad snug and grip the bar a little wider than shoulder width.', 'Sit tall, draw the shoulder blades down, and pull the bar toward the upper chest.', 'Let the bar rise slowly until the arms are straight and the lats stretch.']::text[], array['Keep the torso nearly upright, with a slight lean back.', 'Pull with the elbows, not the hands.', 'Control the return for three seconds.']::text[], array['Pulling the bar behind the neck.', 'Leaning far back and using body weight.', 'Letting the shoulders rise toward the ears at the start.']::text[], array['pull-up', 'seated-cable-row', 'one-arm-dumbbell-row']::text[], false),
  ('seated-cable-row', 'Seated cable row', 'strength', array['back']::text[], array['arms', 'shoulders']::text[], array['cable', 'machine']::text[], 'beginner', array['Sit with the feet braced and grab the handle with straight arms.', 'Pull the handle toward your lower ribs while keeping the torso still.', 'Squeeze the shoulder blades, then return slowly until the arms are straight.']::text[], array['Keep the chest tall and the spine neutral.', 'Let the shoulder blades move; do not lock them in place.', 'Do not rock back and forth for momentum.']::text[], array['Rounding the lower back as the handle returns.', 'Shrugging the shoulders during the pull.', 'Using a jerking motion with the torso.']::text[], array['one-arm-dumbbell-row', 'inverted-row', 'lat-pulldown']::text[], false),
  ('one-arm-dumbbell-row', 'Single-arm dumbbell row', 'strength', array['back']::text[], array['arms', 'shoulders']::text[], array['dumbbells', 'bench']::text[], 'beginner', array['Place one hand and knee on a bench, with the other foot on the floor and a dumbbell in the free hand.', 'Let the dumbbell hang, then row it toward your hip by driving the elbow back.', 'Lower slowly to a full stretch and complete the reps before switching sides.']::text[], array['Keep the hips square to the floor.', 'Think of putting the dumbbell in your back pocket.', 'Do not rotate the torso to lift the weight.']::text[], array['Twisting the torso to gain leverage.', 'Shrugging the working shoulder.', 'Cutting the stretch short at the bottom.']::text[], array['seated-cable-row', 'inverted-row', 'lat-pulldown']::text[], true),
  ('inverted-row', 'Inverted row', 'strength', array['back']::text[], array['arms', 'core']::text[], array['bodyweight', 'bench', 'pull-up-bar']::text[], 'beginner', array['Set a bar at waist height, lie under it, and grip slightly wider than shoulder width.', 'Keep a straight line from head to heels and pull your chest toward the bar.', 'Lower with control until the arms are straight.']::text[], array['Start with the body more upright to make it easier.', 'Squeeze the glutes to keep the hips from sagging.', 'Pull the elbows down and back, not out.']::text[], array['Letting the hips drop and arching the lower back.', 'Pulling the chin forward instead of moving the chest.', 'Bouncing at the bottom.']::text[], array['seated-cable-row', 'one-arm-dumbbell-row', 'lat-pulldown']::text[], false),
  ('face-pull', 'Face pull', 'strength', array['shoulders', 'back']::text[], array['arms']::text[], array['cable', 'resistance-band']::text[], 'intermediate', array['Set a rope at upper chest or eye height and hold one end in each hand.', 'Pull the rope toward your forehead, spreading the hands apart.', 'Squeeze the rear shoulders, then return slowly with control.']::text[], array['Keep the elbows high and wide.', 'Use light weight and focus on the squeeze.', 'Stand tall without leaning back.']::text[], array['Using too much weight and turning it into a row.', 'Pulling the rope down toward the chest instead of the face.', 'Shrugging the shoulders.']::text[], array['rear-delt-fly', 'inverted-row', 'band-shoulder-dislocate']::text[], false),
  ('dumbbell-overhead-press', 'Dumbbell overhead press', 'strength', array['shoulders']::text[], array['arms', 'core']::text[], array['dumbbells']::text[], 'intermediate', array['Stand tall with dumbbells at shoulder height and palms facing forward.', 'Brace your core and press the weights overhead until the arms are straight.', 'Lower slowly back to shoulder height.']::text[], array['Keep the ribs down and glutes tight to avoid arching.', 'Press slightly back and up so the weights finish over the ears.', 'Use a grip just outside shoulder width.']::text[], array['Leaning back and turning it into an incline press.', 'Pressing the weights forward of the body.', 'Flaring the wrists back.']::text[], array['pike-push-up', 'dumbbell-lateral-raise', 'machine-shoulder-press']::text[], false),
  ('machine-shoulder-press', 'Machine shoulder press', 'strength', array['shoulders']::text[], array['arms']::text[], array['machine']::text[], 'beginner', array['Adjust the seat so the handles start around shoulder height.', 'Press the handles overhead until the arms are almost straight.', 'Lower slowly to the starting position.']::text[], array['Keep your back against the pad.', 'Stop just short of locking out to keep tension.', 'Let the shoulders stay down away from the ears.']::text[], array['Setting the seat too low.', 'Arching the back off the pad.', 'Letting the weight drop quickly.']::text[], array['dumbbell-overhead-press', 'pike-push-up', 'dumbbell-lateral-raise']::text[], false),
  ('dumbbell-lateral-raise', 'Dumbbell lateral raise', 'strength', array['shoulders']::text[], array['back']::text[], array['dumbbells']::text[], 'beginner', array['Stand with dumbbells at your sides and a slight bend in the elbows.', 'Raise the arms out to the sides until they reach shoulder height.', 'Lower slowly with control.']::text[], array['Lead with the elbows, not the hands.', 'Keep the shoulders relaxed and down.', 'Use light weights and stop at shoulder height.']::text[], array['Swinging the weights up with momentum.', 'Raising above shoulder height and shrugging.', 'Leaning the torso back.']::text[], array['dumbbell-overhead-press', 'face-pull', 'pike-push-up']::text[], false),
  ('rear-delt-fly', 'Rear delt fly', 'strength', array['shoulders']::text[], array['back']::text[], array['dumbbells']::text[], 'beginner', array['Hinge forward at the hips with a flat back and dumbbells hanging below the shoulders.', 'With a soft elbow bend, raise the arms out to the sides until level with the torso.', 'Squeeze the rear shoulders, then lower slowly.']::text[], array['Keep the neck in line with the spine.', 'Think of reaching the arms long rather than lifting high.', 'Use a light weight and a slow tempo.']::text[], array['Rounding the back during the hinge.', 'Using momentum from the torso.', 'Shrugging the shoulders as the arms rise.']::text[], array['face-pull', 'inverted-row', 'dumbbell-lateral-raise']::text[], false),
  ('pike-push-up', 'Pike push-up', 'strength', array['shoulders']::text[], array['arms', 'core']::text[], array['bodyweight']::text[], 'intermediate', array['Start in a push-up position, then walk your feet toward your hands and lift the hips high.', 'Bend the elbows to lower the top of your head toward the floor in front of your hands.', 'Press back up until the arms are straight.']::text[], array['Keep the hips high throughout.', 'Look at your feet or the floor just behind your hands.', 'Elevate your feet on a step to make it harder.']::text[], array['Lowering the hips and turning it into a regular push-up.', 'Letting the elbows flare wide.', 'Dropping the head too quickly.']::text[], array['dumbbell-overhead-press', 'push-up', 'machine-shoulder-press']::text[], false),
  ('bodyweight-squat', 'Bodyweight squat', 'strength', array['quads', 'glutes']::text[], array['hamstrings', 'core']::text[], array['bodyweight']::text[], 'beginner', array['Stand with feet about shoulder width apart and toes slightly turned out.', 'Push your hips back and bend your knees to lower as far as you can control.', 'Drive through the whole foot to stand back up.']::text[], array['Keep the knees tracking in line with the toes.', 'Reach the hips back before the knees bend.', 'Keep the chest tall and heels grounded.']::text[], array['Letting the knees cave inward.', 'Rising onto the toes.', 'Rounding the lower back at the bottom.']::text[], array['goblet-squat', 'wall-sit', 'step-up']::text[], false),
  ('goblet-squat', 'Goblet squat', 'strength', array['quads', 'glutes']::text[], array['core', 'hamstrings']::text[], array['dumbbells', 'kettlebell']::text[], 'beginner', array['Hold a dumbbell or kettlebell at chest height with both hands.', 'Sit the hips down and back, keeping the weight close to the chest.', 'Descend as far as is comfortable, then drive through the feet to stand.']::text[], array['Use the weight as a counterbalance to stay tall.', 'Keep the elbows inside the knees at the bottom.', 'Pause for a moment at the bottom if you can control it.']::text[], array['Letting the weight pull you forward.', 'Knees collapsing inward.', 'Losing tension at the bottom.']::text[], array['bodyweight-squat', 'barbell-back-squat', 'split-squat']::text[], false),
  ('barbell-back-squat', 'Barbell back squat', 'strength', array['quads', 'glutes']::text[], array['hamstrings', 'core', 'back']::text[], array['barbell']::text[], 'advanced', array['Set the bar on your upper back, brace your core, and stand with feet shoulder width apart.', 'Break at the hips and knees to lower under control, keeping the chest proud.', 'Drive up through the whole foot to return to standing.']::text[], array['Brace as if bracing for a light punch.', 'Keep the bar over the middle of the foot.', 'Use spotters or a rack with safety bars when training heavy.']::text[], array['Letting the knees cave in.', 'Good-morning the weight by folding the chest forward.', 'Adding load before the movement pattern is solid.']::text[], array['goblet-squat', 'leg-press', 'split-squat']::text[], false),
  ('leg-press', 'Leg press', 'strength', array['quads', 'glutes']::text[], array['hamstrings']::text[], array['machine']::text[], 'beginner', array['Sit with your back and hips against the pad and feet shoulder width apart on the platform.', 'Lower the platform until the knees are bent to a comfortable depth.', 'Press back up without locking the knees hard.']::text[], array['Keep the lower back against the pad.', 'Keep the knees tracking over the toes.', 'Leave a small bend at the top.']::text[], array['Going so deep that the hips lift off the pad.', 'Locking the knees aggressively.', 'Placing the feet too low on the platform.']::text[], array['goblet-squat', 'split-squat', 'step-up']::text[], false),
  ('split-squat', 'Split squat', 'strength', array['quads', 'glutes']::text[], array['hamstrings', 'core']::text[], array['bodyweight', 'dumbbells']::text[], 'intermediate', array['Step one foot forward into a long stance and keep the torso tall.', 'Lower straight down until the front knee is around 90 degrees.', 'Push through the front foot to return to the top.']::text[], array['Think down and up, not forward.', 'Keep most of the weight through the front foot.', 'Hold a rail for balance while learning.']::text[], array['Letting the front knee cave inward.', 'Bouncing at the bottom.', 'Taking a stance so short the heel lifts.']::text[], array['walking-lunge', 'step-up', 'goblet-squat']::text[], true),
  ('walking-lunge', 'Walking lunge', 'strength', array['quads', 'glutes']::text[], array['hamstrings', 'core']::text[], array['bodyweight', 'dumbbells']::text[], 'intermediate', array['From standing, step forward and lower until both knees are bent about 90 degrees.', 'Push through the front foot to bring the back foot forward into the next lunge.', 'Continue alternating legs with control.']::text[], array['Keep the torso tall and eyes forward.', 'Aim for a soft landing with each step.', 'Use a shorter step if balance is limited.']::text[], array['Crashing the back knee into the floor.', 'Lunging with a stance that is too narrow.', 'Letting the front knee collapse inward.']::text[], array['split-squat', 'step-up', 'bodyweight-squat']::text[], true),
  ('step-up', 'Step-up', 'strength', array['glutes', 'quads']::text[], array['hamstrings', 'core']::text[], array['bodyweight', 'bench', 'dumbbells']::text[], 'beginner', array['Face a bench or step at about knee height and place one whole foot on it.', 'Drive through that foot to stand on the step without pushing off the back leg.', 'Lower slowly and repeat on the same side before switching.']::text[], array['Keep the knee aligned with the middle toes.', 'Control the descent rather than dropping.', 'Start with a lower step if you feel unstable.']::text[], array['Pushing off the floor with the back foot.', 'Letting the standing knee cave inward.', 'Using a step so high the hips shift sideways.']::text[], array['split-squat', 'goblet-squat', 'walking-lunge']::text[], true),
  ('wall-sit', 'Wall sit', 'strength', array['quads']::text[], array['glutes', 'core']::text[], array['bodyweight']::text[], 'beginner', array['Lean your back against a wall and walk your feet out until the knees are around 90 degrees.', 'Keep the back flat against the wall and hold the position.', 'Stand up before your form breaks.']::text[], array['Keep the knees over the ankles.', 'Breathe normally rather than holding your breath.', 'Choose a depth you can hold with good form.']::text[], array['Letting the knees travel far past the toes.', 'Sliding down until the hips are below the knees.', 'Holding your breath.']::text[], array['bodyweight-squat', 'step-up', 'goblet-squat']::text[], false),
  ('romanian-deadlift', 'Romanian deadlift', 'strength', array['hamstrings', 'glutes']::text[], array['back', 'core']::text[], array['barbell', 'dumbbells']::text[], 'intermediate', array['Start standing with the weights at your thighs and a soft bend in the knees.', 'Push the hips back and let the weights slide down the legs while keeping the back flat.', 'Stop when you feel a strong hamstring stretch, then drive the hips forward to stand.']::text[], array['Think of closing a car door with your hips.', 'Keep the weights close to the legs.', 'Keep the neck in line with the spine.']::text[], array['Rounding the lower back to go deeper.', 'Squatting the weight instead of hinging.', 'Letting the weights drift away from the body.']::text[], array['single-leg-rdl', 'hip-thrust', 'glute-bridge']::text[], false),
  ('single-leg-rdl', 'Single-leg Romanian deadlift', 'strength', array['hamstrings', 'glutes']::text[], array['core']::text[], array['dumbbells']::text[], 'intermediate', array['Hold a dumbbell in one hand and shift your weight onto the opposite leg.', 'Hinge at the hip and let the free leg extend behind you as the chest lowers.', 'Return to standing by driving the hips forward, then switch sides.']::text[], array['Keep the hips square to the floor.', 'Reach the free heel toward the wall behind you.', 'Use a light weight until balance is reliable.']::text[], array['Letting the hips rotate open.', 'Rounding the back at the bottom.', 'Trying to touch the floor instead of stopping at control.']::text[], array['romanian-deadlift', 'glute-bridge', 'step-up']::text[], true),
  ('glute-bridge', 'Glute bridge', 'strength', array['glutes']::text[], array['hamstrings', 'core']::text[], array['bodyweight', 'bench']::text[], 'beginner', array['Lie on your back with knees bent and feet flat, hip width apart.', 'Press through the heels to lift the hips until your body forms a straight line.', 'Squeeze the glutes at the top, then lower slowly.']::text[], array['Tuck the ribs down and avoid arching the lower back.', 'Push the heels into the floor rather than the toes.', 'Pause for one second at the top.']::text[], array['Overextending the lower back at the top.', 'Letting the knees splay out.', 'Rushing the reps.']::text[], array['hip-thrust', 'single-leg-rdl', 'bodyweight-squat']::text[], false),
  ('hip-thrust', 'Hip thrust', 'strength', array['glutes']::text[], array['hamstrings', 'core']::text[], array['barbell', 'bench', 'bodyweight']::text[], 'intermediate', array['Rest your upper back on a bench and place the weight across your hips.', 'Plant the feet and drive the hips up until the torso is parallel to the floor.', 'Squeeze, then lower with control.']::text[], array['Keep the chin slightly tucked.', 'Use a pad across the hips for comfort.', 'Keep the ribs down rather than arching.']::text[], array['Hyperextending the lower back.', 'Letting the knees cave inward.', 'Placing the feet too far away or too close.']::text[], array['glute-bridge', 'romanian-deadlift', 'step-up']::text[], false),
  ('hamstring-curl', 'Machine hamstring curl', 'strength', array['hamstrings']::text[], array['calves']::text[], array['machine']::text[], 'beginner', array['Adjust the pad just above the heels and lie face down with hips flat.', 'Curl the heels toward the glutes without lifting the hips.', 'Lower slowly to a full stretch.']::text[], array['Keep the hips pressed into the pad.', 'Squeeze the hamstrings at the top.', 'Control the lowering phase.']::text[], array['Lifting the hips to help the weight.', 'Swinging the weight up.', 'Cutting the return short.']::text[], array['romanian-deadlift', 'glute-bridge', 'single-leg-rdl']::text[], false),
  ('kettlebell-swing', 'Kettlebell swing', 'conditioning', array['glutes', 'hamstrings']::text[], array['core', 'back']::text[], array['kettlebell']::text[], 'intermediate', array['Stand with feet just wider than the hips and hold the kettlebell in front of you.', 'Hinge at the hips to swing the bell back between the legs, then snap the hips forward.', 'Let the bell float to chest height and guide it back into the next hinge.']::text[], array['The power comes from the hips, not the arms.', 'Keep the core braced and the back flat.', 'Finish tall with glutes squeezed.']::text[], array['Squatting the bell up instead of hinging.', 'Rounding the back during the backswing.', 'Lifting the bell with the shoulders.']::text[], array['hip-thrust', 'romanian-deadlift', 'mountain-climber']::text[], false),
  ('standing-calf-raise', 'Standing calf raise', 'strength', array['calves']::text[], '{}'::text[], array['bodyweight', 'dumbbells']::text[], 'beginner', array['Stand tall with the balls of your feet on a step and heels hanging off.', 'Rise onto your toes as high as you can, pause briefly.', 'Lower slowly until you feel a stretch in the calves.']::text[], array['Keep the knees almost straight.', 'Use a wall for balance if needed.', 'Move slowly through the full range.']::text[], array['Bouncing quickly through tiny reps.', 'Bending the knees to help.', 'Cutting off the stretch at the bottom.']::text[], array['single-leg-calf-raise', 'ankle-mobility', 'step-up']::text[], false),
  ('single-leg-calf-raise', 'Single-leg calf raise', 'strength', array['calves']::text[], array['core']::text[], array['bodyweight']::text[], 'intermediate', array['Stand on one foot with the ball of the foot on a step.', 'Rise onto the toes as high as possible, keeping the ankle stable.', 'Lower slowly and switch sides after the set.']::text[], array['Hold a wall or rail for balance.', 'Keep the ankle moving straight up and down.', 'Use a full range of motion.']::text[], array['Rolling the ankle outward or inward.', 'Going too fast and using momentum.', 'Letting the heel slam down.']::text[], array['standing-calf-raise', 'ankle-mobility', 'step-up']::text[], true),
  ('plank', 'Forearm plank', 'strength', array['core']::text[], array['shoulders', 'glutes']::text[], array['bodyweight']::text[], 'beginner', array['Set the elbows under the shoulders and extend the legs behind you.', 'Squeeze the glutes and brace the core so the body forms a straight line.', 'Hold while breathing steadily, then stop when form breaks.']::text[], array['Push the forearms into the floor.', 'Tuck the ribs down slightly.', 'Stop the set rather than letting the hips sag.']::text[], array['Holding the breath.', 'Letting the hips sag or pike up.', 'Chasing time with poor form.']::text[], array['dead-bug', 'hollow-hold', 'side-plank']::text[], false),
