  ('dead-bug', 'Dead bug', 'strength', array['core']::text[], array['hips']::text[], array['bodyweight']::text[], 'beginner', array['Lie on your back with arms up and knees bent to 90 degrees over the hips.', 'Press the lower back gently into the floor and extend one arm and the opposite leg.', 'Return and repeat on the other side.']::text[], array['Move slowly and keep the lower back connected to the floor.', 'Exhale as you extend.', 'Reduce the range if the back lifts.']::text[], array['Letting the lower back arch.', 'Moving too fast.', 'Holding your breath.']::text[], array['plank', 'hollow-hold', 'cat-cow']::text[], false),
